package employee.management.system;import javax.swing.*;import java.awt.*;import java.awt.event.ActionEvent;import java.awt.event.ActionListener;import java.sql.ResultSet;public class RemoveEmployee extends JFrame implements ActionListener {    JComboBox<String> choiceEMPID;    JButton delete, back;    JLabel textName, textGender, textBirthdate;    RemoveEmployee() {        setLayout(null);        getContentPane().setBackground(new Color(255, 221, 179));        JLabel label = new JLabel("Employee ID");        label.setBounds(50, 50, 100, 30);        label.setFont(new Font("Tahoma", Font.BOLD, 15));        add(label);        choiceEMPID = new JComboBox<>();        choiceEMPID.setBounds(200, 50, 150, 30);        add(choiceEMPID);        try {            conn c = new conn();            ResultSet resultSet = c.statement.executeQuery("SELECT * FROM Employee_Info");            while (resultSet.next()) {                choiceEMPID.addItem(resultSet.getString("Employee_ID"));            }        } catch (Exception e) {            e.printStackTrace();        }        JLabel labelName = new JLabel("Name");        labelName.setBounds(50, 100, 100, 30);        labelName.setFont(new Font("Tahoma", Font.BOLD, 15));        add(labelName);        textName = new JLabel();        textName.setBounds(200, 100, 200, 30);        add(textName);        JLabel labelGender = new JLabel("Gender");        labelGender.setBounds(50, 150, 100, 30);        labelGender.setFont(new Font("Tahoma", Font.BOLD, 15));        add(labelGender);        textGender = new JLabel();        textGender.setBounds(200, 150, 200, 30);        add(textGender);        JLabel labelBirthdate = new JLabel("Birthdate");        labelBirthdate.setBounds(50, 200, 100, 30);        labelBirthdate.setFont(new Font("Tahoma", Font.BOLD, 15));        add(labelBirthdate);        textBirthdate = new JLabel();        textBirthdate.setBounds(200, 200, 200, 30);        add(textBirthdate);        choiceEMPID.addItemListener(e -> {            try {                conn c = new conn();                ResultSet resultSet = c.statement.executeQuery("SELECT pi.Name, pi.Gender, pi.Birthday FROM Personal_Info pi JOIN Employee_Info ei ON pi.Personal_ID = ei.Personal_ID WHERE ei.Employee_ID = '" + choiceEMPID.getSelectedItem() + "'");                if (resultSet.next()) {                    textName.setText(resultSet.getString("Name"));                    textGender.setText(resultSet.getString("Gender"));                    textBirthdate.setText(resultSet.getString("Birthday"));                }            } catch (Exception ex) {                ex.printStackTrace();            }        });        delete = new JButton("Delete");        delete.setBounds(80, 300, 100, 30);        delete.setBackground(SystemColor.activeCaption);        delete.setFont(new Font("Microsoft Sans Serif", Font.BOLD | Font.ITALIC, 10));        delete.addActionListener(this);        add(delete);        back = new JButton("Back");        back.setBounds(220, 300, 100, 30);        back.setBackground(SystemColor.activeCaption);        back.setFont(new Font("Microsoft Sans Serif", Font.BOLD | Font.ITALIC, 10));        back.addActionListener(this);        add(back);        setSize(400, 400);        setLocationRelativeTo(null);        setVisible(true);    }    @Override    public void actionPerformed(ActionEvent e) {        if (e.getSource() == delete) {            try {                conn c = new conn();                String query = "DELETE FROM Employee_Info WHERE Employee_ID = '" + choiceEMPID.getSelectedItem() + "'";                c.statement.executeUpdate(query);                JOptionPane.showMessageDialog(null, "Employee Deleted Successfully");                setVisible(false);                new View_Employee();            } catch (Exception ex) {                ex.printStackTrace();            }        } else {            setVisible(false);            new View_Employee();        }    }    public static void main(String[] args) {        new RemoveEmployee();    }}